#pragma once#include "BaseReader.h"class KDO : public KBaseReader{public:  KDO();  virtual std::string GetType() const  {    return "DO";  }  virtual void GetSettings( tVectoredString_ &set, tParamsCont_ &params )  {    __super::GetSettings( set, params );    set = m_settings;  }protected:  virtual BOOL OnParsingSingleText( std::string &szText, RECTL *rc );private:  int m_CurParameterID;  int m_ReadParams;  tVectoredString_ m_settings;  std::string szLast;};//////////////////////////////////////////////////////////////////////////class KDOFactory : public TIntrusivePtrImpl<IParamReaderFactory>{public:  virtual IParameterReadPtr CreateReader()  {    IParameterReadPtr ptr;    ptr = new KDO();    return ptr;  }};